final class Edge {
    private final int to;
    private final int weight;

    Edge(int to, int weight) {
        this.to = to;
        this.weight = weight;
    }

    int to() {
        return to;
    }

    int weight() {
        return weight;
    }
}

final class QueueEntry {
    private final int vertex;
    private final int distance;

    QueueEntry(int vertex, int distance) {
        this.vertex = vertex;
        this.distance = distance;
    }

    int vertex() {
        return vertex;
    }

    int distance() {
        return distance;
    }
}
